using System;
class HoldTests {static int Main(){var h=new HoldRepeater();h.Update(0x45,0);if(h.Due(349)!=0)throw new Exception("Early repeat");if(h.Due(350)!=0x45){Console.WriteLine("FAIL: held Right must repeat at350ms");return 1;}if(h.Due(400)!=0)throw new Exception("Too fast");if(h.Due(500)!=0x45)throw new Exception("Missing next repeat");h.Update(0,501);if(h.Due(900)!=0)throw new Exception("Repeat after release");h.Update(0x41,1000);if(h.Due(2000)!=0)throw new Exception("OK must not repeat");h.Update(0x9C,2100);if(h.Due(2450)!=0x9C)throw new Exception("Volume hold");h.Update(0x9C,2460);if(h.Due(2600)!=0x9C)throw new Exception("Duplicate report reset timer");h.Update(0,2700);h.Update(0x44,3000,true,650,200);if(h.Due(3649)!=0||h.Due(3650)!=0x44||h.Due(3849)!=0||h.Due(3850)!=0x44)throw new Exception("Custom timing not respected");if(h.Due(33000)!=0)throw new Exception("30 second safety cap");h.Update(0x45,34000,false,350,150);if(h.Due(34500)!=0)throw new Exception("Disabled repeat");Console.WriteLine("PASS: custom timing, disabled repeat and 30 second cap");Console.WriteLine("PASS: hold delay, repeat interval, release stop, OK excluded, volume and duplicate reports");return 0;}}
